package br.com.strumlab.strumming;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import br.com.strumlab.songs.*;
import br.com.strumlab.songbooks.*;
import static br.com.strumlab.strumming.StrummingModels.*;
import static br.com.strumlab.songbooks.BookModels.*;
import static org.assertj.core.api.Assertions.*;
@SpringBootTest
class StrummingIT {
    @Autowired StrummingService strumming;@Autowired SongService songs;@Autowired BookService books;@Autowired JdbcTemplate jdbc;
    SongService.Detail song(){var content=new SongContent(1,"Ritmo autoral "+UUID.randomUUID(),"","G",90,"4/4",0,"manual","","own",List.of(new SongContent.Section("s","verse","Verso",List.of(new SongContent.Line("l",List.of(new SongContent.Token("text",null,"Texto fictício")))))));var s=songs.create(content);return songs.save(s.song().id(),new SongService.Edit(s.draft(),s.baseRevisionId(),s.song().draftVersion()));}
    Edit edit(long version,int bpm){return new Edit(version,"pop-folk-basic",1,bpm,"Manter a mão em movimento",true);}
    @Test void versionedCatalogBindingAndPinnedBookManifest(){var pattern=strumming.pattern("pop-folk-basic",1);assertThat(pattern.events()).hasSize(8);assertThat(pattern.events().stream().filter(Event::play).count()).isEqualTo(6);assertThatThrownBy(()->jdbc.update("UPDATE strumming_pattern SET version=2 WHERE id='pop-folk-basic'")).isInstanceOf(org.springframework.dao.DataAccessException.class);var song=song();UUID id=song.song().id();assertThat(strumming.binding(id).version()).isZero();var binding=strumming.save(id,edit(0,90));var book=books.create(new Config("Livro rítmico","","",new Cover(false,"","unspecified"),new Layout("serif",11,15,1.1,1)));book=books.add(book.book().id(),book.book().version(),id,song.song().currentRevisionId(),false);var item=book.items().getFirst();assertThat(item.strummingSnapshot()).isEqualTo(binding.snapshot());strumming.save(id,edit(1,120));var pinned=books.detail(book.book().id());assertThat(pinned.items().getFirst().strummingSnapshot().bpm()).isEqualTo(90);var manifest=books.begin(book.book().id(),book.book().version()).manifest();assertThat(manifest.items().getFirst().strummingSnapshot().bpm()).isEqualTo(90);var notes=books.updateItem(book.book().id(),book.book().version(),item.id(),item.revisionId(),"Outra nota");assertThat(notes.items().getFirst().strummingSnapshot().bpm()).isEqualTo(90);var refreshed=books.updateStrumming(book.book().id(),notes.book().version(),item.id(),true,null);assertThat(refreshed.items().getFirst().strummingSnapshot().bpm()).isEqualTo(120);var hidden=books.updateStrumming(book.book().id(),refreshed.book().version(),item.id(),false,false);assertThat(hidden.items().getFirst().strummingSnapshot().showInPdf()).isFalse();assertThat(strumming.binding(id).snapshot().showInPdf()).isTrue();strumming.save(id,new Edit(2L,null,1,90,"",true));var removed=books.updateStrumming(book.book().id(),hidden.book().version(),item.id(),true,null);assertThat(removed.items().getFirst().strummingSnapshot()).isNull();assertThat(manifest.items().getFirst().strummingSnapshot().bpm()).isEqualTo(90);}
    @Test void validatesAndScopesBindings(){var s=song();var id=s.song().id();assertThatThrownBy(()->strumming.save(id,edit(0,161))).isInstanceOf(SongProblem.class);assertThatThrownBy(()->strumming.save(id,new Edit(0L,"missing",1,90,"",true))).isInstanceOf(SongProblem.class);strumming.save(id,edit(0,90));assertThatThrownBy(()->strumming.save(id,edit(0,120))).isInstanceOf(SongProblem.class).hasMessageContaining("outra aba");UUID other=UUID.randomUUID();jdbc.update("INSERT INTO workspace(id,name) VALUES (?,?)",other,"Outro dono sint?tico");jdbc.update("UPDATE song SET owner_id=? WHERE id=?",other,id);assertThatThrownBy(()->strumming.binding(id)).isInstanceOf(SongProblem.class).hasMessageContaining("não encontrada");assertThatThrownBy(()->strumming.save(id,edit(1,90))).isInstanceOf(SongProblem.class);}
    @Test void competingEditorsOnlyOneWins()throws Exception{var id=song().song().id();try(var pool=Executors.newFixedThreadPool(2)){var barrier=new CyclicBarrier(2);Callable<Boolean> save=()->{barrier.await();try{strumming.save(id,edit(0,100));return true;}catch(SongProblem e){assertThat(e.status()).isEqualTo(409);return false;}};var a=pool.submit(save);var b=pool.submit(save);assertThat(List.of(a.get(),b.get())).containsExactlyInAnyOrder(true,false);assertThat(strumming.binding(id).version()).isEqualTo(1);}}
}
